-- Cases de Equity Research: ER simplificado (Grão Norte Cafeterias) e ER complexo (Lojas Renner, LREN3).
-- Fonte: docs/cases/Equity Research — Cases, Perguntas e Conteúdo.pdf. Material educacional; nada aqui é recomendação de investimento.
-- Grão Norte, nomes e números do case simplificado são fictícios. No case complexo, a Renner é empresa real e os dados históricos são do PDF; as premissas de projeção são simplificações.

INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  $$er-simplificado$$,
  $$ER simplificado: a recomendação para Luísa$$,
  'equity-research',
  $$Atue como estagiária de research e recomende compra, manter ou venda da Grão Norte Cafeterias a uma gestora de fundo, a partir de teses, cenários e preço-alvo.$$,
  $$Transformar teses e cenários da Grão Norte em uma recomendação clara à Luísa, com preço-alvo, principal risco e o que mudaria sua opinião.$$,
  $$Você é estagiária na equipe de research de uma corretora e vai preparar uma recomendação sobre a Grão Norte Cafeterias para Luísa, gestora de um fundo de ações e cliente da casa. A Grão Norte tem 240 cafeterias próprias no Norte e no Nordeste. A ação custa R$ 20,00, a empresa tem 100 milhões de ações e lucrou R$ 160 milhões em 2025. O horizonte de Luísa é de 12 meses. Todos os nomes, empresas e números são fictícios. Material educacional: nada aqui é recomendação de investimento.$$,
  $${"resumo":"Equity Research (ER) analisa empresas listadas em bolsa, projeta seus resultados e estima quanto suas ações valem, para recomendar a investidores se devem comprar, manter ou vender. Neste case, você prepara a recomendação sobre uma empresa fictícia.","links":[],"cards":[{"titulo":"O que faz uma analista de ER","texto":"Analisa empresas listadas em bolsa, projeta seus resultados e estima quanto suas ações valem, para recomendar a investidores se devem comprar, manter ou vender.","naPratica":"A recomendação orienta investidores, mas nunca garante o resultado."},{"titulo":"Onde atua: sell-side, buy-side e research independente","texto":"No sell-side, em bancos e corretoras, a analista publica relatórios, recomendações e preços-alvo para os clientes da casa. No buy-side, em gestoras de fundos, analisa empresas para decidir o que o próprio fundo vai comprar ou vender. O research independente vende relatórios a investidores, sem vínculo com a distribuição de produtos.","naPratica":"Neste case, você está no sell-side e conversa com uma gestora, cliente da casa."},{"titulo":"Preço-alvo, potencial e regra de recomendação","texto":"O potencial compara o preço-alvo com o preço atual. Cada casa define limites para compra, manter e venda. Por exemplo: compra acima de +15%, venda abaixo de −10% e manter entre os dois.","naPratica":"Preço de R$ 10,00 e preço-alvo de R$ 11,75 resultam em potencial de 17,5%: compra pela regra acima."},{"titulo":"Cenários, tese, riscos e catalisadores","texto":"Uma boa analista não tem um único número: constrói cenários otimista, base e pessimista, atribui probabilidades e entende o que cada um exige da empresa. A tese explica por que o mercado pode estar errado, os riscos mostram o que a derrubaria e os catalisadores indicam quando o mercado pode perceber o valor.","naPratica":"Pergunte sempre: minha visão é diferente do consenso? Por quê? O que me faria mudar de opinião?"}],"comoSeEntra":{"ondeSeTrabalha":"Bancos e corretoras (sell-side), gestoras de fundos (buy-side) e casas de research independente.","formacoes":"O material não define uma formação única. A área pede base em contabilidade, valuation e Excel e conhecimento do setor analisado.","vagas":"A carreira costuma começar no estágio (atualiza planilhas, organiza dados de resultados e apoia relatórios) e segue para analista júnior ou associate, analista, analista sênior ou head de setor e head de research. Os títulos variam entre instituições.","oQueAjuda":"Excel para ligar drivers operacionais ao valuation e testar cenários, escrita direta e sustentada por números, leitura de DRE, balanço e fluxo de caixa e conhecimento de setor. No Brasil, quem publica relatórios precisa ser credenciada como analista de valores mobiliários (Resolução CVM 20), pela Apimec, após exame (CNPI); o CFA também é valorizado, principalmente no buy-side.","quandoRecrutam":"O material não traz um calendário de recrutamento. Acompanhe as páginas de carreira de bancos, corretoras e gestoras."}}$$::jsonb,
  'publicado',
  5
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  $$er-complexo$$,
  $$ER completo: a recomendação para Lojas Renner (LREN3)$$,
  'equity-research',
  $$Avalie a ação da Lojas Renner por DCF e múltiplos de comparáveis, construa cenários e recomende compra, manter ou venda para os próximos 12 meses.$$,
  $$Avaliar LREN3 por DCF e múltiplos, construir cenários e recomendar compra, manter ou venda para os próximos 12 meses, aplicando a regra da casa.$$,
  $$Você trabalha como estagiária em uma equipe de equity research. A Lojas Renner acaba de divulgar o resultado do 3º trimestre de 2026, e a equipe precisa revisar sua recomendação para LREN3. A Renner é uma empresa real, e os dados históricos são públicos. As premissas de projeção são simplificações do case, não estimativas da companhia nem de analistas. Valores em R$ milhões nominais, salvo indicação contrária. Data-base: 06/11/2026. Cotação de referência: R$ 9,93 (fechamento de 06/11/2026). Regra de recomendação: compra se o potencial for maior que +15%; venda se for menor que −10%; manter entre os dois limites. Prazo de entrega: uma semana. Material educacional; não é recomendação de investimento.$$,
  $${"resumo":"Neste case, você faz o trabalho central de uma analista de equity research: avalia uma ação por DCF e por múltiplos de empresas comparáveis, constrói cenários e transforma o resultado em recomendação de compra, manter ou venda para 12 meses.","links":[],"cards":[{"titulo":"Fluxo de caixa descontado (DCF)","texto":"Projeta os fluxos de caixa livres e os traz a valor presente por uma taxa que reflete o risco. Somando o caixa líquido e dividindo pelo número de ações, chega-se ao valor por ação.","naPratica":"O valor terminal costuma representar mais da metade do resultado. Teste sempre a sensibilidade à taxa de desconto e ao crescimento na perpetuidade."},{"titulo":"Múltiplos: P/L e EV/EBITDA","texto":"Comparam o preço com o lucro (P/L) ou o valor da firma com o EBITDA (EV/EBITDA) de empresas semelhantes ou do histórico da própria empresa.","naPratica":"Se comparáveis negociam a 10 vezes o lucro e a empresa deve lucrar R$ 2,00 por ação, uma referência de preço é R$ 20,00. Diferenças de crescimento, margem e risco podem justificar outro múltiplo."},{"titulo":"As três demonstrações com olhar de ER","texto":"DRE: o lucro é recorrente? Balanço: a empresa é sólida? Fluxo de caixa: o lucro vira dinheiro? Cada demonstração responde a uma pergunta diferente da analista.","naPratica":"Um lucro que só cresceu por créditos tributários ou venda de ativos não deve ser multiplicado pelo mesmo P/L do lucro recorrente."},{"titulo":"Da análise à recomendação","texto":"A analista constrói cenários otimista, base e pessimista, atribui probabilidades e calcula o potencial do preço-alvo sobre o preço atual. A tese explica por que o mercado pode estar errado; os riscos mostram o que a derrubaria; os catalisadores indicam quando o mercado pode perceber o valor.","naPratica":"Preço de R$ 10,00 e preço-alvo de R$ 11,75 resultam em potencial de 17,5%: compra pela regra de +15% / −10%."}],"comoSeEntra":{"ondeSeTrabalha":"Bancos e corretoras (sell-side), gestoras de fundos (buy-side) e casas de research independente.","formacoes":"O material não define uma formação única. A área pede base em contabilidade, valuation e Excel e conhecimento do setor analisado.","vagas":"A carreira costuma começar no estágio (atualiza planilhas, organiza dados de resultados e apoia relatórios) e segue para analista júnior ou associate, analista, analista sênior ou head de setor e head de research. Os títulos variam entre instituições.","oQueAjuda":"Excel para ligar drivers operacionais ao valuation e testar cenários, escrita direta e sustentada por números, leitura de DRE, balanço e fluxo de caixa e conhecimento de setor. No Brasil, quem publica relatórios precisa ser credenciada como analista de valores mobiliários (Resolução CVM 20), pela Apimec, após exame (CNPI); o CFA também é valorizado, principalmente no buy-side.","quandoRecrutam":"O material não traz um calendário de recrutamento. Acompanhe as páginas de carreira de bancos, corretoras e gestoras."}}$$::jsonb,
  'publicado',
  6
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO contents (id, title, type, area_id, summary, body, url, minutes, case_ids) VALUES
($$er-o-que-e-er$$, $$O que é Equity Research e onde atua$$, 'artigo', 'equity-research', $$Sell-side, buy-side, research independente, carreira e regulação.$$, $$**Equity Research (ER)** analisa empresas listadas em bolsa, projeta seus resultados e estima quanto suas ações valem, para recomendar a investidores se devem comprar, manter ou vender.

A analista pode atuar em três lugares. No **sell-side**, em bancos e corretoras, publica relatórios, recomendações e preços-alvo para os clientes da casa e conversa com gestores sobre suas teses; por exemplo, depois do resultado trimestral de uma varejista, publica um relatório no mesmo dia e revisa seu preço-alvo. No **buy-side**, em gestoras de fundos, analisa empresas para decidir o que o próprio fundo vai comprar ou vender; por exemplo, defende ao comitê de investimentos aumentar a posição em uma ação que considera barata. No **research independente**, casas de análise vendem relatórios a investidores, sem vínculo com a distribuição de produtos.

A carreira costuma evoluir assim: **estágio** (atualiza planilhas, organiza dados de resultados e apoia relatórios), **analista júnior ou associate** (mantém modelos das empresas cobertas e escreve partes dos relatórios), **analista** (responsável por um grupo de empresas, define recomendações e apresenta teses a clientes), **analista sênior ou head de setor** (lidera a cobertura de um setor e representa a casa diante de investidores) e **head de research** (coordena a equipe, a qualidade e a estratégia das recomendações). O foco passa de construir modelos a defender teses e ser reconhecida pelos investidores. Os títulos e a divisão do trabalho variam entre instituições.

No Brasil, quem publica relatórios de análise precisa ser credenciada como analista de valores mobiliários, conforme a Resolução CVM 20. O credenciamento é feito pela Apimec, após aprovação em exame (o certificado CNPI). O CFA, internacional, é muito valorizado, principalmente no buy-side. Material educacional: nada aqui é recomendação de investimento.$$, NULL, 7, '["er-simplificado","er-complexo"]'::jsonb),
($$er-produtos-research$$, $$Os principais produtos de research$$, 'artigo', 'equity-research', $$Iniciação de cobertura, comentário de resultado, revisão e relacionamento com investidores.$$, $$**Iniciação de cobertura** é o relatório completo publicado quando a casa passa a acompanhar uma empresa. Apresenta negócio, setor, tese, modelo, valuation, riscos e a primeira recomendação. Na prática, é o documento mais longo e detalhado e costuma ser a base de tudo o que vem depois.

**Comentário de resultado** é publicado logo após o release trimestral. Compara os números com a estimativa da casa e com o consenso e indica se a tese muda. Na prática, a analista tem poucas horas entre o release, a teleconferência e a abertura do mercado.

**Revisão** acontece quando fatos ou preço mudam o potencial: a analista revisa premissas e, se necessário, a recomendação. Na prática, uma ação que caiu muito pode passar de manter para compra mesmo com resultados piores, se o preço caiu mais que o valor.

**Relacionamento** reúne conversas com investidores e empresas: reuniões com gestores, visitas e contato com a área de relações com investidores (RI). Na prática, perguntas específicas à RI, como as vendas das lojas abertas no último ano, ajudam a calibrar as premissas.$$, NULL, 5, '["er-simplificado"]'::jsonb),
($$er-vagas-er$$, $$O que as vagas de ER exigem$$, 'artigo', 'equity-research', $$Excel, escrita, contabilidade e conhecimento de setor.$$, $$**Excel.** Monte modelos que liguem drivers operacionais, como lojas e vendas por loja, às demonstrações e ao valuation. Teste cenários e sensibilidades.

**Escrita.** Resuma uma tese em poucas linhas claras. Gestores leem muitos relatórios por dia e valorizam conclusões diretas, sustentadas por números.

**Contabilidade.** Leia DRE, balanço e fluxo de caixa, separe efeitos pontuais e entenda de onde vem o lucro.

**Conhecimento de setor.** Entenda concorrência, consumidores, regulação e tendências. O setor explica muito do que acontece com cada empresa.$$, NULL, 4, '["er-simplificado"]'::jsonb),
($$er-da-analise-a-recomendacao$$, $$Da análise à recomendação$$, 'glossario', 'equity-research', $$Cenários, potencial, regra de recomendação, tese, riscos e catalisadores.$$, $$**Cenários.** Uma boa analista não tem um único número. Ela constrói cenários otimista, base e pessimista, atribui probabilidades e entende o que cada um exige da empresa.

**Potencial e regra de recomendação.** O potencial compara preço-alvo e preço atual: preço-alvo ÷ preço atual − 1. Cada casa define limites para compra, manter e venda. Por exemplo: compra acima de +15%, venda abaixo de −10% e manter entre os dois. Com preço de R$ 10,00 e preço-alvo de R$ 11,75, o potencial é de 17,5%: compra pela regra acima. O potencial é medido sobre o preço atual, e não sobre o preço-alvo.

**Tese, riscos e catalisadores.** A tese explica por que o mercado pode estar errado. Os riscos mostram o que derrubaria a tese, e os catalisadores indicam quando o mercado pode perceber o valor. Pergunte-se: minha visão é diferente do consenso? Por quê? O que faria eu mudar de opinião?$$, NULL, 5, '["er-simplificado","er-complexo"]'::jsonb),
($$er-demonstracoes$$, $$As três demonstrações financeiras com olhar de ER$$, 'artigo', 'equity-research', $$Como ler DRE, balanço e fluxo de caixa em busca de recorrência, solidez e geração de caixa.$$, $$**DRE: o lucro é recorrente?** Mostra como receitas, custos e despesas viram lucro em um período. Olhe se as vendas cresceram por lojas novas ou nas mesmas lojas, se as margens melhoraram por preço, custo ou mix e se o lucro tem efeitos não recorrentes. Na prática, um lucro que só cresceu por créditos tributários ou venda de ativos não deve ser multiplicado pelo mesmo P/L do lucro recorrente.

**Balanço patrimonial: a empresa é sólida?** Mostra ativos, obrigações e patrimônio líquido em uma data. Olhe quanto de caixa e dívida a empresa tem, se estoques e recebíveis crescem mais rápido que as vendas e se há riscos de crédito na carteira de clientes. Na prática, caixa líquido dá flexibilidade para atravessar períodos ruins, pagar dividendos ou recomprar ações.

**Fluxo de caixa: o lucro vira dinheiro?** Mostra as entradas e saídas de caixa na operação, nos investimentos e nos financiamentos. Olhe se a operação gera caixa compatível com o lucro, quanto a empresa investe em lojas e tecnologia e quanto sobra para os acionistas. Na prática, uma empresa que lucra mas consome caixa todo ano em capital de giro pode ter um valor menor do que o lucro sugere.$$, NULL, 7, '["er-complexo"]'::jsonb),
($$er-metodos-valuation$$, $$Métodos de valuation em ER$$, 'artigo', 'equity-research', $$DCF, múltiplos (P/L e EV/EBITDA), dividendos descontados e soma das partes.$$, $$**Fluxo de caixa descontado (DCF).** Projeta os fluxos de caixa livres e os traz a valor presente por uma taxa que reflete o risco. Somando o caixa líquido e dividindo pelo número de ações, chega-se ao valor por ação. Na prática, o valor terminal costuma representar mais da metade do resultado. Teste sempre a sensibilidade à taxa de desconto e ao crescimento na perpetuidade.

**Múltiplos: P/L e EV/EBITDA.** Comparam o preço com o lucro (P/L) ou o valor da firma com o EBITDA (EV/EBITDA) de empresas semelhantes ou do histórico da própria empresa. Se comparáveis negociam a 10 vezes o lucro e a empresa deve lucrar R$ 2,00 por ação, uma referência de preço é R$ 20,00. Diferenças de crescimento, margem e risco podem justificar outro múltiplo.

**Dividendos descontados.** Avalia a ação pelos dividendos futuros trazidos a valor presente. É mais usado em empresas maduras e com política de distribuição estável, como bancos e empresas de energia. Em empresas que reinvestem quase todo o lucro para crescer, esse método tende a subestimar o valor.

**Soma das partes.** Avalia separadamente cada negócio de uma empresa e soma os valores. Uma varejista com uma financeira própria pode ter o varejo avaliado por múltiplos de varejo e a financeira por múltiplos do setor financeiro.$$, NULL, 8, '["er-complexo"]'::jsonb)
ON CONFLICT (id) DO NOTHING;

